export function searchTitles(titles, query) {
  const q = query.trim().toLowerCase();
  const out = [];
  for (let i = 0; i < titles.length; i++) {
    if (q === '' || titles[i].toLowerCase().includes(q)) out.push(titles[i]);
  }
  return out;
}

